import { test, expect } from '@playwright/test';

test.describe('Image Upload Preview', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/upload'); // Replace with the actual URL of the upload page
  });

  test('should display image preview after upload', async ({ page }) => {
    const filePath = 'path/to/image.jpg'; // Replace with the actual image path
    await page.getByLabel('Upload Image').setInputFiles(filePath);

    const preview = page.getByRole('img', { name: /image preview/i });
    await expect(preview).toBeVisible();
    await expect(preview).toHaveAttribute('src', /image.jpg$/); // Adjust based on the expected src
  });

  test('should not display image preview if no image is uploaded', async ({ page }) => {
    const preview = page.getByRole('img', { name: /image preview/i });
    await expect(preview).not.toBeVisible();
  });
});
